<div class="top noprint"><a class="btn alt sm" href="/staff/purchase-orders">← Purchase orders</a><div><a class="btn alt" href="/staff/purchase-orders/<?= (int) $p['id'] ?>.pdf">Download PDF</a> <?php if ($p['semail']): ?><form method="post" class="inline"><?= csrf_field() ?><input type="hidden" name="action" value="email"><button class="btn alt" data-confirm="E-mail this purchase order to <?= e($p['semail']) ?>?">E-mail to supplier</button></form> <?php endif; ?><button class="btn" data-print>Print</button></div></div>
<div class="inv"><div class="hd"><div><h2 style="margin:0">Purchase order</h2><b><?= e($p['number']) ?></b><br>Date: <?= e(fmt_date($p['order_date'])) ?><br>Expected: <?= e(fmt_date($p['expected_date'])) ?><br>Status: <?= e(PO_STATUSES[$p['status']]) ?><?= $p['received_at'] ? ' (' . e(fmt_date($p['received_at'])) . ')' : '' ?></div>
<div style="text-align:right"><b>To: <?= e($p['sname']) ?></b><br><?= nl2br(e((string) $p['saddress'])) ?><br><?= e(trim((string) $p['sphone'] . ' ' . $p['semail'])) ?><?= $p['sgstin'] ? '<br>GSTIN: ' . e($p['sgstin']) : '' ?></div></div>
<div class="tw"><table><tr><th>#</th><th>Description</th><th class="right">Qty</th><th class="right">Unit cost</th><th class="right">Amount</th></tr>
<?php foreach ($lines as $n => $l): ?><tr><td><?= $n + 1 ?></td><td><?= e($l['description']) ?><?= $l['iname'] ? ' <span class="muted">(stock: ' . e($l['iname']) . ')</span>' : '' ?></td><td class="right"><?= e(rtrim(rtrim(number_format((float) $l['qty'], 2, '.', ''), '0'), '.')) ?> <?= e((string) $l['unit']) ?></td><td class="right"><?= e(money($l['unit_cost'])) ?></td><td class="right"><?= e(money($l['amount'])) ?></td></tr><?php endforeach; ?></table></div>
<table class="tot"><tr><td>Total (excl. tax)</td><td class="right"><?= e(money($p['total'])) ?></td></tr></table>
<?php if ($p['notes']): ?><p class="mt"><b>Notes</b><br><?= nl2br(e($p['notes'])) ?></p><?php endif; ?></div>
<?php if ($p['status'] === 'ordered'): ?><div class="card mt noprint"><form method="post" class="inline"><?= csrf_field() ?><input type="hidden" name="action" value="receive"><button class="btn" data-confirm="Mark everything as received and add to stock?">Mark received</button></form>
<form method="post" class="inline"><?= csrf_field() ?><input type="hidden" name="action" value="cancel"><button class="btn danger sm" data-confirm="Cancel this purchase order?">Cancel PO</button></form></div><?php endif; ?>
